<?php
declare(strict_types=1);
require_once __DIR__ . '/functions.php';

$page = (string)($_GET['page'] ?? 'home');

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        if ($page === 'register') {
            $name = post('name');
            $email = strtolower(post('email'));
            $password = post('password');
            $role = post('role');

            if (strlen($name) < 2 || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 8 || !in_array($role, ['parent', 'student'], true)) {
                throw new RuntimeException('Enter a valid name, email, role, and a password of at least 8 characters.');
            }

            $profile = $role === 'student'
                ? [post('bio'), post('subjects'), post('qualifications'), max(0, (int) post('experience_years')), post('hourly_rate') !== '' ? (float) post('hourly_rate') : null, post('availability'), post('teaching_mode') ?: 'both', post('location'), post('languages')]
                : ['', '', '', 0, null, '', 'both', post('location'), post('languages')];

            if ($role === 'student' && (strlen($profile[0]) < 20 || $profile[1] === '' || $profile[2] === '' || $profile[5] === '' || $profile[7] === '')) {
                throw new RuntimeException('Tutor/Student accounts must include a bio, subjects, qualifications, availability, and location.');
            }

            $statement = db()->prepare('INSERT INTO users(name,email,password,role,bio,subjects,qualifications,experience_years,hourly_rate,availability,teaching_mode,location,languages) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');
            $statement->execute([$name, $email, password_hash($password, PASSWORD_DEFAULT), $role, ...$profile]);
            flash('success', 'Account created. You can now sign in.');
            redirect('login');
        }
        if ($page === 'login') {
            $submittedEmail = strtolower(post('email'));
            $submittedPassword = post('password');
            $statement = db()->prepare('SELECT * FROM users WHERE email = ?');
            $statement->execute([$submittedEmail]);
            $account = $statement->fetch();

            if (!$account || !password_verify($submittedPassword, $account['password'])) {
                throw new RuntimeException('The email or password is incorrect.');
            }
            if ($account['is_suspended']) {
                throw new RuntimeException('This account has been suspended.');
            }

            session_regenerate_id(true);
            $_SESSION['user'] = ['id' => (int) $account['id'], 'name' => $account['name'], 'email' => $account['email'], 'role' => $account['role']];
            flash('success', 'Welcome back, ' . $account['name'] . '!');
            redirect('dashboard');
        }
        if ($page === 'logout') { require_login(); $_SESSION=[]; session_destroy(); header('Location: index.php'); exit; }
        if ($page === 'profile') {
            $u=require_login(); $fields=['name','bio','subjects','qualifications','availability','location','languages','education_level','learning_goals']; $values=[]; foreach($fields as $f)$values[]=post($f);
            $rate=post('hourly_rate')!==''?(float)post('hourly_rate'):null; $years=max(0,(int)post('experience_years')); $mode=in_array(post('teaching_mode'),['online','in_person','both'],true)?post('teaching_mode'):'both';
            $s=db()->prepare('UPDATE users SET name=?,bio=?,subjects=?,qualifications=?,availability=?,location=?,languages=?,education_level=?,learning_goals=?,hourly_rate=?,experience_years=?,teaching_mode=? WHERE id=?'); $s->execute([...$values,$rate,$years,$mode,$u['id']]);
            $_SESSION['user']['name']=$values[0]; flash('success','Your profile has been updated.'); redirect('profile');
        }
        if ($page === 'job_form') {
            $u=require_role('parent','admin'); $id=(int)($_GET['id']??0); $subjectList=implode(', ',array_unique(array_filter(array_map('trim',explode(',',post('subject')))))); $data=[post('title'),post('tutee_name'),(int)post('age'),$subjectList,post('education_level'),post('description'),post('schedule'),(float)post('payment'),post('location'),post('teaching_mode')];
            if(strlen($data[0])<5 || !$data[3] || strlen($data[5])<10 || $data[7]<=0) throw new RuntimeException('Complete all required job details and enter a valid budget.');
            if($id){$s=db()->prepare('UPDATE tutoring_jobs SET title=?,tutee_name=?,age=?,subject=?,education_level=?,description=?,schedule=?,payment=?,location=?,teaching_mode=? WHERE id=? AND user_id=?');$s->execute([...$data,$id,$u['id']]);flash('success','Job updated.');}
            else{$s=db()->prepare('INSERT INTO tutoring_jobs(title,tutee_name,age,subject,education_level,description,schedule,payment,location,teaching_mode,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([...$data,$u['id']]);flash('success','Your tutoring job is now live.');}
            redirect('my_jobs');
        }
        if ($page === 'apply') {
            $u=require_role('student'); $job=(int)post('job_id'); $s=db()->prepare("SELECT * FROM tutoring_jobs WHERE id=? AND status='open'");$s->execute([$job]);$j=$s->fetch();if(!$j)throw new RuntimeException('This job is no longer accepting applications.');
            $s=db()->prepare('INSERT INTO applications(job_id,student_id,cover_note) VALUES(?,?,?)');$s->execute([$job,$u['id'],post('cover_note')]);notify((int)$j['user_id'],$u['name'].' applied to “'.$j['title'].'”.',$job);flash('success','Application sent successfully.');redirect('applications');
        }
        if ($page === 'save_job') { $u=require_role('student');$job=(int)post('job_id');$sql=db_driver()==='sqlite'?'INSERT OR IGNORE INTO saved_jobs(user_id,job_id) VALUES(?,?)':(config_value('DATABASE_URL')!==''?'INSERT INTO saved_jobs(user_id,job_id) VALUES(?,?) ON CONFLICT DO NOTHING':'INSERT IGNORE INTO saved_jobs(user_id,job_id) VALUES(?,?)');$s=db()->prepare($sql);$s->execute([$u['id'],$job]);flash('success','Job saved.');redirect('jobs'); }
        if ($page === 'application_action') {
            $u=require_login();$id=(int)post('application_id');$action=post('action');
            $s=db()->prepare('SELECT a.*,j.user_id,j.title FROM applications a JOIN tutoring_jobs j ON j.id=a.job_id WHERE a.id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)throw new RuntimeException('Application not found.');
            if($action==='withdraw' && (int)$a['student_id']===$u['id']){$s=db()->prepare("UPDATE applications SET status='withdrawn' WHERE id=? AND status IN ('pending','shortlisted')");$s->execute([$id]);flash('success','Application withdrawn.');redirect('applications');}
            if((int)$a['user_id']!==$u['id'] && $u['role']!=='admin')throw new RuntimeException('You cannot manage this application.');
            if(!in_array($action,['shortlisted','accepted','rejected'],true))throw new RuntimeException('Invalid application action.');
            db()->beginTransaction();$s=db()->prepare('UPDATE applications SET status=? WHERE id=?');$s->execute([$action,$id]);
            if($action==='accepted'){$s=db()->prepare("UPDATE tutoring_jobs SET status='assigned' WHERE id=?");$s->execute([$a['job_id']]);$s=db()->prepare("UPDATE applications SET status='rejected' WHERE job_id=? AND id<>? AND status IN ('pending','shortlisted')");$s->execute([$a['job_id'],$id]);$welcome="Your application has been accepted. Let’s use this private chat to arrange the first class.";$s=db()->prepare('INSERT INTO messages(sender_id,receiver_id,job_id,body) VALUES(?,?,?,?)');$s->execute([$u['id'],$a['student_id'],$a['job_id'],$welcome]);}
            db()->commit();$notice=$action==='accepted'?'Your application for “'.$a['title'].'” was accepted. A private conversation is ready in Messages so you can arrange the class.':'Your application for “'.$a['title'].'” was '.$action.'.';notify((int)$a['student_id'],$notice,(int)$a['job_id']);flash('success',$action==='accepted'?'Tutor approved. A private conversation has been created in Messages.':'Application marked '.$action.'.');redirect('my_jobs',['id'=>$a['job_id']]);
        }
        if ($page === 'job_status') {
            $u=require_login();$id=(int)post('job_id');$status=post('status');if(!in_array($status,['in_progress','completed','cancelled'],true))throw new RuntimeException('Invalid job status.');
            $s=db()->prepare('SELECT * FROM tutoring_jobs WHERE id=?');$s->execute([$id]);$j=$s->fetch();if(!$j || ((int)$j['user_id']!==$u['id'] && $u['role']!=='admin'))throw new RuntimeException('You cannot update this job.');
            $s=db()->prepare('UPDATE tutoring_jobs SET status=? WHERE id=?');$s->execute([$status,$id]);$s=db()->prepare("SELECT student_id FROM applications WHERE job_id=? AND status='accepted'");$s->execute([$id]);if($sid=$s->fetchColumn())notify((int)$sid,'“'.$j['title'].'” is now '.str_replace('_',' ',$status).'.',$id);flash('success','Job status updated.');redirect('my_jobs',['id'=>$id]);
        }
        if ($page === 'send_message') {
            $u=require_login();$to=(int)post('receiver_id');$body=post('body');$job=(int)post('job_id')?:null;if($to===$u['id']||strlen($body)<1||strlen($body)>3000)throw new RuntimeException('Enter a valid message.');
            $s=db()->prepare('SELECT id FROM users WHERE id=? AND is_suspended=0');$s->execute([$to]);if(!$s->fetch())throw new RuntimeException('Recipient not found.');$s=db()->prepare('INSERT INTO messages(sender_id,receiver_id,job_id,body) VALUES(?,?,?,?)');$s->execute([$u['id'],$to,$job,$body]);notify($to,$u['name'].' sent you a message.',$job);redirect('messages',['with'=>$to,'job'=>$job]);
        }
        if ($page === 'review') {
            $u=require_login();$job=(int)post('job_id');$rating=(int)post('rating');if($rating<1||$rating>5)throw new RuntimeException('Choose a rating from 1 to 5.');
            $s=db()->prepare("SELECT j.user_id,a.student_id FROM tutoring_jobs j JOIN applications a ON a.job_id=j.id AND a.status='accepted' WHERE j.id=? AND j.status='completed'");$s->execute([$job]);$x=$s->fetch();if(!$x)throw new RuntimeException('Only completed jobs can be reviewed.');$reviewee=$u['id']==(int)$x['user_id']?(int)$x['student_id']:(int)$x['user_id'];if(!in_array($u['id'],[(int)$x['user_id'],(int)$x['student_id']],true))throw new RuntimeException('You were not part of this job.');
            $s=db()->prepare('INSERT INTO reviews(job_id,reviewer_id,reviewee_id,rating,comment) VALUES(?,?,?,?,?)');$s->execute([$job,$u['id'],$reviewee,$rating,post('comment')]);notify($reviewee,$u['name'].' left you a review.',$job);flash('success','Thanks for sharing your review.');redirect('dashboard');
        }
        if ($page === 'report') { $u=require_login();$job=(int)post('job_id');if(strlen(post('reason'))<5)throw new RuntimeException('Tell us why you are reporting this listing.');$s=db()->prepare('INSERT INTO reports(reporter_id,job_id,reason) VALUES(?,?,?)');$s->execute([$u['id'],$job,post('reason')]);flash('success','Report submitted for admin review.');redirect('job',['id'=>$job]); }
        if ($page === 'notifications') { $u=require_login();$s=db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$s->execute([$u['id']]);redirect('notifications'); }
        if ($page === 'admin_action') {
            require_role('admin');$action=post('action');$id=(int)post('id');
            if($action==='toggle_suspend'){$s=db()->prepare('UPDATE users SET is_suspended=1-is_suspended WHERE id=? AND role<>\'admin\'');$s->execute([$id]);}
            elseif($action==='verify'){$s=db()->prepare('UPDATE users SET is_verified=1 WHERE id=?');$s->execute([$id]);}
            elseif($action==='resolve'){$s=db()->prepare("UPDATE reports SET status='resolved' WHERE id=?");$s->execute([$id]);}
            elseif($action==='delete_user'){$s=db()->prepare("DELETE FROM users WHERE id=? AND role<>'admin'");$s->execute([$id]);if(!$s->rowCount())throw new RuntimeException('Administrators cannot be deleted.');}
            else throw new RuntimeException('Invalid admin action.');flash('success','Admin action completed.');redirect('admin');
        }
        if ($page === 'admin_user') {
            require_role('admin');$id=(int)post('id');$role=post('role');if(!in_array($role,['parent','student'],true))throw new RuntimeException('Choose Parent or Tutor/Student.');
            $name=post('name');$email=strtolower(post('email'));if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid name and email address.');
            $s=db()->prepare("UPDATE users SET name=?,email=?,role=?,bio=?,subjects=?,qualifications=?,experience_years=?,hourly_rate=?,availability=?,teaching_mode=?,location=?,languages=?,is_verified=?,is_suspended=? WHERE id=? AND role<>'admin'");
            $s->execute([$name,$email,$role,post('bio'),post('subjects'),post('qualifications'),max(0,(int)post('experience_years')),post('hourly_rate')!==''?(float)post('hourly_rate'):null,post('availability'),post('teaching_mode')?:'both',post('location'),post('languages'),isset($_POST['is_verified'])?1:0,isset($_POST['is_suspended'])?1:0,$id]);
            if(!$s->rowCount()){$check=db()->prepare("SELECT id FROM users WHERE id=? AND role<>'admin'");$check->execute([$id]);if(!$check->fetch())throw new RuntimeException('This account cannot be edited.');}
            flash('success','User account updated.');redirect('admin');
        }
    } catch (PDOException $ex) {
        if(db()->inTransaction())db()->rollBack();
        $message=$ex->getCode()==='23000'?'That record already exists or conflicts with existing data.':'The database could not complete the request.'; flash('error',$message); redirect($page);
    } catch (RuntimeException $ex) { if(db()->inTransaction())db()->rollBack();flash('error',$ex->getMessage());redirect($page); }
}

