if ($page==='messages') { $u=require_login();$s=db()->prepare('SELECT u.id,u.name,MAX(m.created_at) last_at FROM messages m JOIN users u ON u.id=CASE WHEN m.sender_id=? THEN m.receiver_id ELSE m.sender_id END WHERE m.sender_id=? OR m.receiver_id=? GROUP BY u.id,u.name ORDER BY last_at DESC');$s->execute([$u['id'],$u['id'],$u['id']]);$people=$s->fetchAll();$with=(int)($_GET['with']??($people[0]['id']??0));$thread=[];$peer=null;if($with){$s=db()->prepare('SELECT id,name FROM users WHERE id=?');$s->execute([$with]);$peer=$s->fetch();$s=db()->prepare('SELECT * FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at');$s->execute([$u['id'],$with,$with,$u['id']]);$thread=$s->fetchAll();$s=db()->prepare('UPDATE messages SET is_read=1 WHERE sender_id=? AND receiver_id=?');$s->execute([$with,$u['id']]);}render_header('Messages');?>
